/* Host regression test for the VIC-20 ("vic20-vic") and C16/Plus/4 ("c16-ted") systems: Thor Tracker's own player
 * (cbm/cbm_player.c) on the VIC's sound unit (cbm/cbm_vic.c, VICE's model) and the TED's (cbm/cbm_ted.c, plus4emu's),
 * with the TED's D/A samples streamed from its timer interrupts.
 *
 * Fixtures: cbm_test_song.h, generated by tools/audio/prepare_cbm.py from tools/audio/cbm/cbm_song.py and the Python
 * reference player tools/audio/cbm/cbm_ref.py: per song the image's leading bytes and the reference's batches in time
 * order, each kind byte 'R' (reset) / 'T' (tick) / 'I' (TED timer interrupt, only those that wrote), u32 LE timeline
 * cycle since the reset, for 'T' u16 LE order, u8 row, u8 tick-in-row (the position before the tick), then u8 count and
 * count x (u8 register, u8 value).
 *
 * Checks: the period tables (A-4 on every variant, every lane's range within +-50 cents and its neighbours outside);
 * the loader's accept/reject cases (header, tables, instruments, envelopes, samples, lane ranges by chip and video,
 * placement rules, effect parameters), each reject at its byte; the machine's batches equal to the reference's for every
 * tick and interrupt of every fixture song; actual audio: the shortest songs' A-4 by zero crossings (VIC PAL soprano
 * a = 39: 444.07 Hz; TED PAL P = 252: 439.84 Hz) and pitch spot checks per lane and variant, the shared master volume
 * scaling every lane, the owner's volume envelope shaping every lane, TED noise vs square, D/A sample playback (timer
 * rate, frame order, level steps), the $3FE no-toggle decay, mutes (silence, the other lanes sounding, chip state and
 * writes bit-identical to an unmuted run), seeks bit-identical to straight play, the order fallback and unreachable
 * rows, live edits (envelope, video, speed, volume, multispeed, the other chip), auditions and their release ends, the
 * ops tables; tick cost. Audio thresholds are first estimates, not yet confirmed by a run (marked "unverified").
 *
 * Build and run: tools/audio/run_native_host_test.sh [evidence-dir] (arguments: the evidence directory and the
 * exportSamples directory). Writes <dir>/cbm_trace_<name>.txt for every fixture song (the reference's ticks) and, when
 * present in the samples directory, for vic-demo, vic-shortest, ted-demo and ted-shortest (.cbimg, 3000 ticks each):
 * one line per batch, "R 0 0:", "T <k> <cycle> @<order>,<row>,<tick>:" or "I <n> <cycle>:" (n counts every interrupt
 * since the reset; only interrupts that wrote get a line), then " RR=VV" per write; tools/audio/cbm/cbm_reference_check.py
 * compares them with the reference. Also cbm_<name>.wav (20 s of each fixture song) and cbm_vic_shortest.wav /
 * cbm_ted_shortest.wav (the shortest songs, 2 s). */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "blip_buf.h"
#include "cbm_image.h"
#include "cbm_machine.h"
#include "cbm_player.h"
#include "cbm_ted.h"
#include "cbm_test_song.h"
#include "cbm_vic.h"
#include "chip_engine.h"

static int failures = 0;
static int checks = 0;
#define EXPECT(cond, ...)                                              \
    do {                                                               \
        ++checks;                                                      \
        if (!(cond)) {                                                 \
            ++failures;                                                \
            printf("  FAIL %s:%d: ", __FILE__, __LINE__);              \
            printf(__VA_ARGS__);                                       \
            printf("\n");                                              \
        }                                                              \
    } while (0)

#define RATE 48000
#define VIC CB_CHIP_VIC
#define TED CB_CHIP_TED
#define PAL CB_VIDEO_PAL
#define NTSC CB_VIDEO_NTSC
#define A4 57

static const char* g_dir = ".";
static float g_tick[CBM_MAX_TICK_FRAMES * 2];

/* ---- helpers --------------------------------------------------------------------------------- */

static void w16(uint8_t* p, int v) {
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
}

static void w32(uint8_t* p, uint32_t v) {
    for (int i = 0; i < 4; ++i) p[i] = (uint8_t)(v >> (8 * i));
}

static CbmImage* new_image(void) { return (CbmImage*)calloc(1, sizeof(CbmImage)); }

static int load(CbmImage* img, const uint8_t* bytes) {
    if (bytes != img->bytes) memcpy(img->bytes, bytes, CB_IMAGE_SIZE);
    return cb_load_image(img, img->bytes[CB_H_CHIP]);
}

/* A one-order image (64 rows) with every lane on the empty pattern at data offset 0 (one run byte: 128 empty rows). */
static void song_init(uint8_t* b, int chip, int video, int speed, int volume, int timer) {
    memset(b, 0, CB_IMAGE_SIZE);
    memcpy(b, CB_MAGIC, 4);
    b[CB_H_LAYOUT] = CB_LAYOUT;
    b[CB_H_CHIP] = (uint8_t)chip;
    b[CB_H_VIDEO] = (uint8_t)video;
    b[CB_H_MULTISPEED] = 1;
    b[CB_H_SPEED] = (uint8_t)speed;
    w16(b + CB_H_ORDERS, 1);
    w16(b + CB_H_LOOP, 0);
    b[CB_H_VOLUME] = (uint8_t)volume;
    b[CB_H_TIMER] = (uint8_t)timer;
    b[CB_OFF_DATA] = 0xFF;
    w32(b + CB_H_DATA_SIZE, 1);
    b[CB_OFF_ROWS] = 64;
}

/* Appends bytes to the data region; returns their data offset. */
static int data(uint8_t* b, const uint8_t* p, int n) {
    const uint32_t off = cb_u32(b + CB_H_DATA_SIZE);
    memcpy(b + CB_OFF_DATA + off, p, (size_t)n);
    w32(b + CB_H_DATA_SIZE, off + (uint32_t)n);
    return (int)off;
}

static void set_orders(uint8_t* b, int count, int loop) {
    w16(b + CB_H_ORDERS, count);
    w16(b + CB_H_LOOP, loop);
}

static void set_rows(uint8_t* b, int order, int rows) { b[CB_OFF_ROWS + order] = (uint8_t)(rows & 255); }

static void set_pattern(uint8_t* b, int order, int channel, int offset) {
    w16(b + CB_OFF_ORDERS + 2 * (CB_MAX_CHANNELS * order + channel), offset);
}

static uint8_t* record(uint8_t* b, int slot) { return b + CB_OFF_INSTRUMENTS + CB_INSTRUMENT_SIZE * (slot - 1); }

static uint8_t* new_record(uint8_t* b, int slot) {
    if (b[CB_H_INSTRUMENTS] < slot) b[CB_H_INSTRUMENTS] = (uint8_t)slot;
    uint8_t* r = record(b, slot);
    memset(r, 0, CB_INSTRUMENT_SIZE);
    for (int k = 0; k < CB_ENVELOPE_COUNT; ++k) {
        r[CB_I_ENVELOPES + CB_ENVELOPE_BYTES * k + 3] = CB_ENV_NONE;
        r[CB_I_ENVELOPES + CB_ENVELOPE_BYTES * k + 4] = CB_ENV_NONE;
    }
    return r;
}

static void tone(uint8_t* b, int slot, int wave) {
    uint8_t* r = new_record(b, slot);
    r[CB_I_FLAGS] = CB_FLAG_DEFINED | CB_KIND_TONE;
    r[CB_I_WAVE] = (uint8_t)wave;
}

static void sample_instrument(uint8_t* b, int slot, int s, int root, int loop, int loop_start) {
    uint8_t* r = new_record(b, slot);
    r[CB_I_FLAGS] = CB_FLAG_DEFINED | CB_KIND_SAMPLE;
    r[CB_I_SAMPLE] = (uint8_t)s;
    r[CB_I_ROOT] = (uint8_t)root;
    r[CB_I_LOOP] = (uint8_t)loop;
    w16(r + CB_I_LOOP_START, loop_start);
}

/* Envelope k of a slot (loop / release CB_ENV_NONE for none); returns the image offset of its first value. */
static int envelope(uint8_t* b, int slot, int k, const uint8_t* values, int n, int loop, int release) {
    const int off = data(b, values, n);
    uint8_t* e = record(b, slot) + CB_I_ENVELOPES + CB_ENVELOPE_BYTES * k;
    w16(e, off);
    e[2] = (uint8_t)n;
    e[3] = (uint8_t)loop;
    e[4] = (uint8_t)release;
    e[5] = 0;
    return CB_OFF_DATA + off;
}

/* Sample s; returns the image offset of its first frame. */
static int sample(uint8_t* b, int s, const uint8_t* frames, int n) {
    const int off = data(b, frames, n);
    uint8_t* e = b + CB_OFF_SAMPLES + CB_SAMPLE_ENTRY_SIZE * s;
    w32(e, (uint32_t)off);
    w32(e + 4, (uint32_t)n);
    if (b[CB_H_SAMPLES] <= s) b[CB_H_SAMPLES] = (uint8_t)(s + 1);
    return CB_OFF_DATA + off;
}

/* A lane's pattern: `note` keyed with `slot` on row 0, then empty rows. */
static int key_pattern(uint8_t* b, int note, int slot) {
    const uint8_t p[] = {0x03, (uint8_t)note, (uint8_t)slot, 0x80 | 126};
    return data(b, p, (int)sizeof p);
}

/* The default master volume of a chip. */
static int vmax(int chip) { return chip == VIC ? CB_VIC_MAX_VOLUME : CB_TED_MAX_VOLUME; }

/* One order of `rows` rows at speed 6: `note` keyed with a tone instrument of `wave` on `channel`, other lanes empty. */
static void tone_song(uint8_t* b, int chip, int video, int channel, int note, int wave, int rows) {
    song_init(b, chip, video, 6, vmax(chip), 0);
    tone(b, 1, wave);
    set_rows(b, 0, rows);
    set_pattern(b, 0, channel, key_pattern(b, note, 1));
}

static CbmMachine* machine(int chip) {
    CbmMachine* m = cbm_create(RATE, chip);
    EXPECT(m != NULL, "machine created");
    return m;
}

/* Runs `ticks` ticks appending float stereo frames to buf (capacity in frames; NULL: discarded). Returns the frames. */
static long run(CbmMachine* m, int ticks, float* buf, long capacity) {
    long frames = 0;
    for (int t = 0; t < ticks; ++t) {
        const int n = cbm_tick(m, g_tick);
        if (n <= 0) break;
        if (buf && frames < capacity) {
            const long copy = frames + n <= capacity ? n : capacity - frames;
            memcpy(buf + 2 * frames, g_tick, sizeof(float) * 2 * (size_t)copy);
        }
        frames += n;
    }
    return frames;
}

static float* frames_buffer(long frames) { return (float*)calloc((size_t)(frames + CBM_MAX_TICK_FRAMES) * 2, sizeof(float)); }

static double rms(const float* st, long from, long to) {
    double s = 0;
    for (long i = from; i < to; ++i) s += (double)st[2 * i] * st[2 * i];
    return to > from ? sqrt(s / (double)(to - from)) : 0;
}

static double peak_to_peak(const float* st, long from, long to) {
    float lo = 0, hi = 0;
    for (long i = from; i < to; ++i) {
        if (st[2 * i] < lo) lo = st[2 * i];
        if (st[2 * i] > hi) hi = st[2 * i];
    }
    return (double)hi - lo;
}

/* Fundamental by upward zero crossings with 5 % hysteresis: (crossings - 1) periods between the first and the last. */
static double measure_freq(const float* st, long from, long to) {
    float peak = 0;
    for (long i = from; i < to; ++i)
        if (fabsf(st[2 * i]) > peak) peak = fabsf(st[2 * i]);
    const float h = peak * 0.05f;
    int state = 0;
    long first = -1, last = -1, count = 0;
    for (long i = from; i < to; ++i) {
        const float x = st[2 * i];
        if (x > h) {
            if (state < 0) {
                if (first < 0) first = i;
                last = i;
                ++count;
            }
            state = 1;
        } else if (x < -h) {
            state = -1;
        }
    }
    return count >= 3 ? (double)(count - 1) * RATE / (double)(last - first) : 0;
}

/* Normalised autocorrelation at `lag` frames. */
static double autocorr(const float* st, long from, long to, int lag) {
    double xy = 0, xx = 0, yy = 0;
    for (long i = from; i + lag < to; ++i) {
        const double x = st[2 * i], y = st[2 * (i + lag)];
        xy += x * y;
        xx += x * x;
        yy += y * y;
    }
    return xx > 0 && yy > 0 ? xy / sqrt(xx * yy) : 0;
}

static void write_wav(const char* name, const float* st, long frames) {
    char path[512];
    snprintf(path, sizeof path, "%s/%s", g_dir, name);
    FILE* f = fopen(path, "wb");
    if (!f) {
        printf("  (cannot write %s)\n", path);
        return;
    }
    const uint32_t bytes = (uint32_t)(frames * 4);
    const uint32_t hdr[] = {0x46464952u, 36 + bytes, 0x45564157u, 0x20746d66u, 16, 0x00020001u, RATE, RATE * 4,
                            0x00100004u, 0x61746164u, bytes};
    fwrite(hdr, sizeof hdr, 1, f);
    for (long i = 0; i < frames * 2; ++i) {
        const float v = st[i] < -1 ? -1 : st[i] > 1 ? 1 : st[i];
        const int16_t s = (int16_t)lrintf(v * 32767);
        fwrite(&s, 2, 1, f);
    }
    fclose(f);
}

static double variant_clock(int variant) { return CBM_CLOCK_HZ[variant]; }

/* ---- traces ---------------------------------------------------------------------------------- */

typedef struct TraceCtx {
    FILE* text;            /* the text dump, or NULL */
    const uint8_t* ref;    /* the fixture's batches, or NULL */
    uint32_t ref_bytes, at;
    long batches, writes, mismatches;
    char first[256];       /* the first mismatch */
    /* collected interrupt batches that wrote (D/A test) */
    int irq_count;
    int64_t irq_index[64];
    uint8_t irq_val[64];
} TraceCtx;

static uint32_t rd32(const uint8_t* p) { return (uint32_t)p[0] | (uint32_t)p[1] << 8 | (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24; }

static void on_trace(void* vctx, int kind, int64_t index, int64_t cycle, int order, int row, int tick, const CbWrite* w,
                     int n) {
    TraceCtx* t = (TraceCtx*)vctx;
    if (kind == CBM_TRACE_OFF || (kind == CBM_TRACE_TIMER && n == 0)) return;
    ++t->batches;
    t->writes += n;
    if (kind == CBM_TRACE_TIMER && n > 0 && t->irq_count < 64) {
        t->irq_index[t->irq_count] = index;
        t->irq_val[t->irq_count] = w[n - 1].val;
        ++t->irq_count;
    }
    if (t->text) {
        if (kind == CBM_TRACE_RESET) fprintf(t->text, "R 0 0:");
        else if (kind == CBM_TRACE_TICK) fprintf(t->text, "T %lld %lld @%d,%d,%d:", (long long)index, (long long)cycle, order, row, tick);
        else fprintf(t->text, "I %lld %lld:", (long long)index, (long long)cycle);
        for (int i = 0; i < n; ++i) fprintf(t->text, " %02X=%02X", w[i].reg, w[i].val);
        fputc('\n', t->text);
    }
    if (!t->ref) return;
    if (t->at >= t->ref_bytes) {
        if (!t->mismatches++) snprintf(t->first, sizeof t->first, "batch %ld (%c at cycle %lld): the reference has no more", t->batches, kind, (long long)cycle);
        return;
    }
    const uint8_t* r = t->ref + t->at;
    const int rk = r[0];
    const uint32_t rc = rd32(r + 1);
    int p = 5, ro = -1, rr = -1, rt = -1;
    if (rk == 'T') {
        ro = r[5] | r[6] << 8;
        rr = r[7];
        rt = r[8];
        p = 9;
    }
    const int rn = r[p];
    const uint8_t* rw = r + p + 1;
    t->at += (uint32_t)(p + 1 + 2 * rn);
    int ok = rk == kind && rc == (uint32_t)cycle && rn == n && (rk != 'T' || (ro == order && rr == row && rt == tick));
    for (int i = 0; ok && i < n; ++i) ok = rw[2 * i] == w[i].reg && rw[2 * i + 1] == w[i].val;
    if (!ok && !t->mismatches++) {
        int len = snprintf(t->first, sizeof t->first, "batch %ld: engine %c %lld @%d,%d,%d n=%d", t->batches, kind, (long long)cycle,
                           order, row, tick, n);
        for (int i = 0; i < n && len < 200; ++i) len += snprintf(t->first + len, sizeof t->first - (size_t)len, " %02X=%02X", w[i].reg, w[i].val);
        len += snprintf(t->first + len, sizeof t->first - (size_t)len, " | reference %c %u @%d,%d,%d n=%d", rk, rc, ro, rr, rt, rn);
        for (int i = 0; i < rn && len < 250; ++i)
            len += snprintf(t->first + len, sizeof t->first - (size_t)len, " %02X=%02X", rw[2 * i], rw[2 * i + 1]);
    }
}

static FILE* open_text(const char* name) {
    char path[512];
    snprintf(path, sizeof path, "%s/cbm_trace_%s.txt", g_dir, name);
    FILE* f = fopen(path, "w");
    if (!f) printf("  (cannot write %s)\n", path);
    return f;
}

static const CbtSong* fixture(const char* name) {
    for (int i = 0; i < CBT_SONG_COUNT; ++i)
        if (!strcmp(CBT_SONGS[i].name, name)) return &CBT_SONGS[i];
    return NULL;
}

static CbmImage* fixture_image(const CbtSong* s) {
    CbmImage* img = new_image();
    memcpy(img->bytes, s->image, s->image_bytes);
    const int r = cb_load_image(img, img->bytes[CB_H_CHIP]);
    EXPECT(r == 0, "%s: fixture image loads (%s at %d)", s->name, img->info.problem ? img->info.problem : "", img->info.problem_offset);
    return img;
}

/* ---- tables and lanes ------------------------------------------------------------------------ */

static double lane_freq(int chip, int video, int channel, int note) {
    const int v = chip * 2 + video;
    if (chip == VIC) {
        const int s = 2 - channel;
        return variant_clock(v) / (64.0 * (1 << s) * cbp_period(v, note * 64, s));
    }
    return variant_clock(v) / (8.0 * cbp_period(v, note * 64, 0));
}

static double cents(double f, int note) { return 1200.0 * log2(f / (440.0 * pow(2.0, (note - 57) / 12.0))); }

static void test_tables(void) {
    printf("tables and lanes\n");
    EXPECT(cbp_period(CB_VARIANT_VIC_PAL, A4 * 64, 0) == 39, "VIC PAL soprano A-4 period 39 (%d)", cbp_period(CB_VARIANT_VIC_PAL, A4 * 64, 0));
    EXPECT(cbp_period(CB_VARIANT_VIC_NTSC, A4 * 64, 0) == 36, "VIC NTSC soprano A-4 period 36 (%d)", cbp_period(CB_VARIANT_VIC_NTSC, A4 * 64, 0));
    EXPECT(cbp_period(CB_VARIANT_TED_PAL, A4 * 64, 0) == 252, "TED PAL A-4 reload 252 (%d)", cbp_period(CB_VARIANT_TED_PAL, A4 * 64, 0));
    EXPECT(cbp_period(CB_VARIANT_TED_NTSC, A4 * 64, 0) == 254, "TED NTSC A-4 reload 254 (%d)", cbp_period(CB_VARIANT_TED_NTSC, A4 * 64, 0));
    EXPECT(fabs(lane_freq(VIC, PAL, 2, A4) - 444.07) < 0.01, "VIC PAL A-4 = 444.07 Hz (%.3f)", lane_freq(VIC, PAL, 2, A4));
    EXPECT(fabs(lane_freq(VIC, NTSC, 2, A4) - 443.89) < 0.01, "VIC NTSC A-4 = 443.89 Hz (%.3f)", lane_freq(VIC, NTSC, 2, A4));
    EXPECT(fabs(lane_freq(TED, PAL, 0, A4) - 439.84) < 0.01, "TED PAL A-4 = 439.84 Hz (%.3f)", lane_freq(TED, PAL, 0, A4));
    EXPECT(fabs(lane_freq(TED, NTSC, 0, A4) - 440.40) < 0.01, "TED NTSC A-4 = 440.40 Hz (%.3f)", lane_freq(TED, NTSC, 0, A4));
    EXPECT(cbp_period(CB_VARIANT_VIC_PAL, 0, 2) == 128 && cbp_period(CB_VARIANT_VIC_PAL, CBP_PITCH_MAX, 0) >= 1, "VIC periods clamp to 1..128");
    EXPECT(cbp_period(CB_VARIANT_TED_PAL, 0, 0) == 1024 && cbp_period(CB_VARIANT_TED_PAL, CBP_PITCH_MAX, 0) >= 2, "TED reloads clamp to 2..1024");
    EXPECT(cbp_sample_step(60 * 64, 60) == 65536 && cbp_sample_step(72 * 64, 60) == 131072 && cbp_sample_step(48 * 64, 60) == 32768,
           "sample step: root 65536, octaves x2 / x0.5");
    EXPECT(cbp_sample_step(CBP_PITCH_MAX, 24) == (1u << 24) && cbp_sample_step(0, 108) >= 1, "sample step clamps to 1..2^24");
    /* Tonal lanes: every note of the range within +-50 cents, the notes just outside it not. */
    const struct { int chip, video, channel; } lanes[] = {
        {VIC, PAL, 0}, {VIC, PAL, 1}, {VIC, PAL, 2}, {VIC, NTSC, 0}, {VIC, NTSC, 1}, {VIC, NTSC, 2}, {TED, PAL, 0}, {TED, NTSC, 0},
    };
    for (size_t i = 0; i < sizeof lanes / sizeof lanes[0]; ++i) {
        int lo = 0, hi = 0;
        cb_lane_range(lanes[i].chip, lanes[i].video, lanes[i].channel, &lo, &hi);
        double worst = 0;
        for (int n = lo; n <= hi; ++n) {
            const double c = fabs(cents(lane_freq(lanes[i].chip, lanes[i].video, lanes[i].channel, n), n));
            if (c > worst) worst = c;
        }
        EXPECT(worst <= 50.0, "chip %d video %d lane %d: %d..%d within 50 cents (worst %.1f)", lanes[i].chip, lanes[i].video,
               lanes[i].channel, lo, hi, worst);
        EXPECT(lo == 0 || fabs(cents(lane_freq(lanes[i].chip, lanes[i].video, lanes[i].channel, lo - 1), lo - 1)) > 50.0,
               "chip %d video %d lane %d: note %d below the range is out of tune", lanes[i].chip, lanes[i].video, lanes[i].channel, lo - 1);
        EXPECT(hi >= 127 || fabs(cents(lane_freq(lanes[i].chip, lanes[i].video, lanes[i].channel, hi + 1), hi + 1)) > 50.0,
               "chip %d video %d lane %d: note %d above the range is out of tune", lanes[i].chip, lanes[i].video, lanes[i].channel, hi + 1);
    }
    int lo, hi;
    EXPECT(!cb_lane_range(VIC, PAL, 3, &lo, &hi) && lo == 0 && hi == 127, "VIC noise lane: rates 0..127");
    EXPECT(!cb_lane_range(TED, PAL, 1, &lo, &hi) && lo == 33 && hi == 127, "TED voice 2: 33..127");
    EXPECT(!cb_lane_range(TED, NTSC, 2, &lo, &hi) && lo == 24 && hi == 108, "TED DAC: 24..108");
    EXPECT(cb_lane_range(TED, PAL, 3, &lo, &hi) < 0 && cb_lane_range(VIC, PAL, 4, &lo, &hi) < 0, "no lane past the chip's");
}

/* ---- loader ---------------------------------------------------------------------------------- */

typedef struct VicBase {
    int ch0_note, ch0_inst, ch2_mask, ch2_fx0, ch2_fx1, env_vol;
} VicBase;

/* Two orders of 16 rows: bass note 40, soprano note 60 with V0A and 037, noise rate 100; slot 1 with a volume envelope. */
static void vic_base(uint8_t* b, VicBase* o) {
    song_init(b, VIC, PAL, 6, 15, 0);
    tone(b, 1, CB_WAVE_SQUARE);
    static const uint8_t vol[] = {15, 10, 5};
    o->env_vol = envelope(b, 1, CB_ENV_VOLUME, vol, 3, CB_ENV_NONE, CB_ENV_NONE);
    const int a = key_pattern(b, 40, 1);
    o->ch0_note = CB_OFF_DATA + a + 1;
    o->ch0_inst = CB_OFF_DATA + a + 2;
    const uint8_t p2[] = {0x0B, 60, 1, CB_FX_VOLUME, 10, CB_FX_ARPEGGIO, 0x37, 0x80 | 126};
    const int c = data(b, p2, (int)sizeof p2);
    o->ch2_mask = CB_OFF_DATA + c;
    o->ch2_fx0 = CB_OFF_DATA + c + 3;
    o->ch2_fx1 = CB_OFF_DATA + c + 5;
    const int d = key_pattern(b, 100, 1);
    set_orders(b, 2, 0);
    for (int ord = 0; ord < 2; ++ord) {
        set_rows(b, ord, 16);
        set_pattern(b, ord, 0, a);
        set_pattern(b, ord, 1, 0);
        set_pattern(b, ord, 2, c);
        set_pattern(b, ord, 3, d);
    }
}

typedef struct TedBase {
    int ch0_inst, ch0_fx, ch1_inst, ch2_inst, ch2_fx, frame0, env_wave;
} TedBase;

/* One order of 16 rows: voice 1 A-4 with W01, voice 2 A-4 with the noise instrument, the DAC note 60 with T14;
 * slots 1 square (wave envelope 1, 0), 2 noise, 3 the looped sample 0 (frames 0..8). */
static void ted_base(uint8_t* b, TedBase* o) {
    song_init(b, TED, PAL, 6, 8, 12);
    tone(b, 1, CB_WAVE_SQUARE);
    static const uint8_t wave[] = {1, 0};
    o->env_wave = envelope(b, 1, CB_ENV_WAVE, wave, 2, CB_ENV_NONE, CB_ENV_NONE);
    tone(b, 2, CB_WAVE_NOISE);
    static const uint8_t frames[] = {0, 1, 2, 3, 4, 5, 6, 7, 8};
    o->frame0 = sample(b, 0, frames, 9);
    sample_instrument(b, 3, 0, 60, 1, 2);
    const uint8_t p0[] = {0x07, A4, 1, CB_FX_WAVE, 1, 0x80 | 126};
    const int a = data(b, p0, (int)sizeof p0);
    o->ch0_inst = CB_OFF_DATA + a + 2;
    o->ch0_fx = CB_OFF_DATA + a + 3;
    const int c = key_pattern(b, A4, 2);
    o->ch1_inst = CB_OFF_DATA + c + 2;
    const uint8_t p2[] = {0x07, 60, 3, CB_FX_TIMER, 20, 0x80 | 126};
    const int d = data(b, p2, (int)sizeof p2);
    o->ch2_inst = CB_OFF_DATA + d + 2;
    o->ch2_fx = CB_OFF_DATA + d + 3;
    set_rows(b, 0, 16);
    set_pattern(b, 0, 0, a);
    set_pattern(b, 0, 1, c);
    set_pattern(b, 0, 2, d);
}

/* Loads a copy of `base` with one byte changed and expects a reject at `offset` (or an accept with offset -1). */
static CbmImage* g_scratch;

static void expect_load(const uint8_t* base, int chip, int at, int value, int offset, const char* what) {
    memcpy(g_scratch->bytes, base, CB_IMAGE_SIZE);
    if (at >= 0) g_scratch->bytes[at] = (uint8_t)value;
    const int r = cb_load_image(g_scratch, chip);
    if (offset < 0) {
        EXPECT(r == 0 && g_scratch->info.loaded == CB_LOADED, "%s: accepted (%s at %d)", what,
               g_scratch->info.problem ? g_scratch->info.problem : "", g_scratch->info.problem_offset);
    } else {
        EXPECT(r < 0 && g_scratch->info.loaded != CB_LOADED && g_scratch->info.problem && g_scratch->info.problem_offset == offset,
               "%s: rejected at byte %d (%s, got %d: %s)", what, offset, r < 0 ? "rejected" : "accepted", g_scratch->info.problem_offset,
               g_scratch->info.problem ? g_scratch->info.problem : "-");
    }
}

static void test_loader(void) {
    printf("loader\n");
    g_scratch = new_image();
    uint8_t* vb = (uint8_t*)calloc(1, CB_IMAGE_SIZE);
    uint8_t* tb = (uint8_t*)calloc(1, CB_IMAGE_SIZE);
    VicBase v;
    TedBase t;
    vic_base(vb, &v);
    ted_base(tb, &t);
    expect_load(vb, VIC, -1, 0, -1, "VIC base image");
    expect_load(tb, TED, -1, 0, -1, "TED base image");
    memcpy(g_scratch->bytes, vb, CB_IMAGE_SIZE);
    cb_load_image(g_scratch, VIC);
    EXPECT(g_scratch->info.orders == 2 && g_scratch->info.rows[0] == 16 && g_scratch->info.start_speed[1] == 6 &&
               g_scratch->info.channels == 4 && g_scratch->info.chip == VIC && g_scratch->info.instruments == 1,
           "VIC base info derived");

    /* Header. */
    expect_load(vb, VIC, 0, 'X', 0, "magic");
    expect_load(vb, VIC, CB_H_LAYOUT, 2, CB_H_LAYOUT, "layout 2");
    expect_load(vb, TED, -1, 0, CB_H_CHIP, "a VIC image for the TED ops");
    expect_load(tb, VIC, -1, 0, CB_H_CHIP, "a TED image for the VIC ops");
    expect_load(vb, VIC, CB_H_CHIP, 2, CB_H_CHIP, "chip 2");
    expect_load(vb, VIC, CB_H_VIDEO, 2, CB_H_VIDEO, "video 2");
    expect_load(vb, VIC, CB_H_MULTISPEED, 0, CB_H_MULTISPEED, "multispeed 0");
    expect_load(vb, VIC, CB_H_MULTISPEED, 5, CB_H_MULTISPEED, "multispeed 5");
    expect_load(vb, VIC, CB_H_MULTISPEED, 4, -1, "multispeed 4");
    expect_load(vb, VIC, CB_H_SPEED, 0, CB_H_SPEED, "speed 0");
    expect_load(vb, VIC, CB_H_INSTRUMENTS, 65, CB_H_INSTRUMENTS, "65 instruments");
    expect_load(vb, VIC, CB_H_ORDERS, 0, CB_H_ORDERS, "order count 0");
    expect_load(vb, VIC, CB_H_LOOP, 2, CB_H_LOOP, "loop order = the order count");
    expect_load(vb, VIC, CB_H_SAMPLES, 1, CB_H_SAMPLES, "a sample count on the VIC");
    expect_load(vb, VIC, CB_H_VOLUME, 16, CB_H_VOLUME, "VIC volume 16");
    expect_load(vb, VIC, CB_H_VOLUME, 15, -1, "VIC volume 15");
    expect_load(tb, TED, CB_H_VOLUME, 9, CB_H_VOLUME, "TED volume 9");
    expect_load(vb, VIC, CB_H_TIMER, 1, CB_H_TIMER, "a DAC timer on the VIC");
    expect_load(tb, TED, CB_H_TIMER, 255, -1, "TED timer 255");
    expect_load(vb, VIC, 18, 1, 17, "header reserved byte 18");
    expect_load(vb, VIC, CB_H_DATA_SIZE + 2, 2, CB_H_DATA_SIZE, "data size above the region");
    expect_load(vb, VIC, 40, 1, 24, "header reserved byte 40");
    expect_load(vb, VIC, 5000, 1, CB_OFF_RESERVED, "reserved byte 5000");
    /* Tables. */
    expect_load(vb, VIC, CB_OFF_ROWS + 2, 1, CB_OFF_ROWS + 2, "rows of an order past the count");
    expect_load(vb, VIC, CB_OFF_ORDERS + 2 * 4 * 2, 1, CB_OFF_ORDERS + 2 * 4 * 2, "a pattern of an order past the count");
    expect_load(tb, TED, CB_OFF_ORDERS + 6, 1, CB_OFF_ORDERS + 6, "a TED channel 3 pattern");
    expect_load(vb, VIC, CB_OFF_ORDERS + 1, 0x7F, CB_OFF_ORDERS, "a pattern offset past the data size");
    /* Instruments and envelopes. */
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS + 32, CB_FLAG_DEFINED, CB_OFF_INSTRUMENTS + 32, "an instrument past the count");
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS, CB_FLAG_DEFINED | 0x08, CB_OFF_INSTRUMENTS, "instrument flags");
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS, CB_FLAG_DEFINED | CB_KIND_SAMPLE, CB_OFF_INSTRUMENTS, "a sample instrument on the VIC");
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS + CB_I_WAVE, CB_WAVE_NOISE, CB_OFF_INSTRUMENTS + CB_I_WAVE, "a noise instrument on the VIC");
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS + CB_I_WAVE, 0, CB_OFF_INSTRUMENTS + CB_I_WAVE, "a tone without a wave");
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS + CB_I_ROOT, 60, CB_OFF_INSTRUMENTS + CB_I_SAMPLE, "sample fields of a tone");
    expect_load(vb, VIC, CB_OFF_INSTRUMENTS + 5, 1, CB_OFF_INSTRUMENTS + 5, "instrument byte 5");
    expect_load(vb, VIC, v.env_vol, 16, v.env_vol, "VIC volume envelope value 16");
    expect_load(vb, VIC, v.env_vol, 15, -1, "VIC volume envelope value 15");
    const int env0 = CB_OFF_INSTRUMENTS + CB_I_ENVELOPES;
    expect_load(vb, VIC, env0 + 3, 3, env0 + 3, "envelope loop at its length");
    expect_load(vb, VIC, env0 + 3, 2, -1, "envelope loop at its last step");
    expect_load(vb, VIC, env0 + 4, 0, env0 + 4, "envelope release 0");
    expect_load(vb, VIC, env0 + 4, 3, env0 + 4, "envelope release at its length");
    expect_load(vb, VIC, env0 + 5, 1, env0 + 5, "envelope reserved byte");
    expect_load(vb, VIC, env0 + CB_ENVELOPE_BYTES * CB_ENV_WAVE + 3, 0, env0 + CB_ENVELOPE_BYTES * CB_ENV_WAVE,
                "an empty envelope with a loop");
    memcpy(g_scratch->bytes, vb, CB_IMAGE_SIZE);
    g_scratch->bytes[env0 + 3] = 1;
    g_scratch->bytes[env0 + 4] = 1;
    EXPECT(cb_load_image(g_scratch, VIC) < 0 && g_scratch->info.problem_offset == env0 + 4, "envelope release at its loop rejected");
    expect_load(tb, TED, t.env_wave + 1, 3, t.env_wave + 1, "TED wave envelope value 3");
    expect_load(tb, TED, t.env_wave + 1, 2, t.ch0_inst, "a wave envelope with noise makes slot 1 voice 2 only");
    /* Samples. */
    expect_load(tb, TED, t.frame0 + 4, 9, t.frame0 + 4, "sample frame 9");
    expect_load(tb, TED, CB_OFF_SAMPLES + 4, 0, CB_OFF_SAMPLES + 4, "a sample without frames");
    expect_load(tb, TED, CB_OFF_SAMPLES + 2, 0x7F, CB_OFF_SAMPLES, "a sample past the data size");
    expect_load(tb, TED, CB_OFF_SAMPLES + 12, 1, CB_OFF_SAMPLES + 8, "a sample entry past the count");
    const int r3 = CB_OFF_INSTRUMENTS + 2 * CB_INSTRUMENT_SIZE;
    expect_load(tb, TED, r3 + CB_I_ROOT, 23, r3 + CB_I_ROOT, "sample root 23");
    expect_load(tb, TED, r3 + CB_I_ROOT, 109, r3 + CB_I_ROOT, "sample root 109");
    expect_load(tb, TED, r3 + CB_I_ROOT, 108, -1, "sample root 108");
    expect_load(tb, TED, r3 + CB_I_LOOP_START, 9, r3 + CB_I_LOOP_START, "loop start at the sample's length");
    expect_load(tb, TED, r3 + CB_I_LOOP, 2, r3 + CB_I_LOOP, "loop flag 2");
    expect_load(tb, TED, r3 + CB_I_SAMPLE, 1, r3 + CB_I_SAMPLE, "a sample the image does not have");
    expect_load(tb, TED, r3 + CB_I_WAVE, 1, r3 + CB_I_WAVE, "a wave byte on a sample instrument");
    expect_load(tb, TED, r3 + CB_I_ENVELOPES + 2, 1, r3 + CB_I_ENVELOPES + 2, "a volume envelope on a sample instrument");
    /* Patterns: lane ranges by chip and video. */
    expect_load(vb, VIC, v.ch0_note, 52, -1, "VIC PAL bass note 52");
    expect_load(vb, VIC, v.ch0_note, 53, v.ch0_note, "VIC PAL bass note 53");
    expect_load(vb, VIC, v.ch0_note, 12, v.ch0_note, "VIC PAL bass note 12");
    expect_load(vb, VIC, v.ch0_note, CB_NOTE_OFF, -1, "an OFF on the bass");
    expect_load(vb, VIC, CB_H_VIDEO, NTSC, -1, "the VIC base image as NTSC");
    memcpy(g_scratch->bytes, vb, CB_IMAGE_SIZE);
    g_scratch->bytes[CB_H_VIDEO] = NTSC;
    g_scratch->bytes[v.ch0_note] = 50;
    EXPECT(cb_load_image(g_scratch, VIC) < 0 && g_scratch->info.problem_offset == v.ch0_note, "VIC NTSC bass note 50 rejected (PAL: fine)");
    expect_load(vb, VIC, v.ch0_note, 50, -1, "VIC PAL bass note 50");
    expect_load(tb, TED, t.ch0_inst - 1, 32, t.ch0_inst - 1, "TED voice 1 note 32");
    expect_load(tb, TED, t.ch0_inst - 1, 109, t.ch0_inst - 1, "TED voice 1 note 109");
    expect_load(tb, TED, t.ch1_inst - 1, 127, -1, "TED voice 2 note 127");
    expect_load(tb, TED, t.ch2_inst - 1, 23, t.ch2_inst - 1, "TED DAC note 23");
    /* Placement rules. */
    expect_load(vb, VIC, v.ch0_inst, 2, v.ch0_inst, "an undefined instrument");
    expect_load(vb, VIC, v.ch0_inst, 0, v.ch0_inst, "instrument byte 0");
    expect_load(tb, TED, t.ch0_inst, 2, t.ch0_inst, "the noise instrument on voice 1");
    expect_load(tb, TED, t.ch0_inst, 3, t.ch0_inst, "a sample instrument on voice 1");
    expect_load(tb, TED, t.ch1_inst, 3, t.ch1_inst, "a sample instrument on voice 2");
    expect_load(tb, TED, t.ch1_inst, 1, -1, "a square instrument on voice 2");
    expect_load(tb, TED, t.ch2_inst, 1, t.ch2_inst, "a tone instrument on the DAC lane");
    /* Row bytes and effects. */
    expect_load(vb, VIC, v.ch2_mask, 0x1B, v.ch2_mask, "a mask byte with bit 4");
    expect_load(vb, VIC, v.ch2_mask, 0x0F, v.ch2_mask, "three effect columns");
    expect_load(vb, VIC, v.ch2_fx0 + 1, 16, v.ch2_fx0, "V10 on the VIC");
    expect_load(vb, VIC, v.ch2_fx0 + 1, 15, -1, "V0F on the VIC");
    expect_load(tb, TED, t.ch0_fx, CB_FX_VOLUME, -1, "V01 on the TED");
    memcpy(g_scratch->bytes, tb, CB_IMAGE_SIZE);
    g_scratch->bytes[t.ch0_fx] = CB_FX_VOLUME;
    g_scratch->bytes[t.ch0_fx + 1] = 9;
    EXPECT(cb_load_image(g_scratch, TED) < 0 && g_scratch->info.problem_offset == t.ch0_fx, "V09 on the TED rejected");
    expect_load(vb, VIC, v.ch2_fx0, CB_FX_TIMER, v.ch2_fx0, "Txx on the VIC");
    expect_load(vb, VIC, v.ch2_fx0, CB_FX_WAVE, v.ch2_fx0, "Wxx on the VIC");
    expect_load(vb, VIC, v.ch2_fx0, 12, v.ch2_fx0, "Cxx (unknown)");
    expect_load(vb, VIC, v.ch2_fx0, 36, v.ch2_fx0, "an effect code above Z");
    memcpy(g_scratch->bytes, vb, CB_IMAGE_SIZE);
    g_scratch->bytes[v.ch2_fx1] = CB_FX_JUMP;
    g_scratch->bytes[v.ch2_fx1 + 1] = 2;
    EXPECT(cb_load_image(g_scratch, VIC) < 0 && g_scratch->info.problem_offset == v.ch2_fx1, "B02 with two orders rejected");
    g_scratch->bytes[v.ch2_fx1 + 1] = 1;
    EXPECT(cb_load_image(g_scratch, VIC) == 0, "B01 with two orders accepted");
    memcpy(g_scratch->bytes, vb, CB_IMAGE_SIZE);
    g_scratch->bytes[v.ch2_fx1] = CB_FX_SPEED;
    g_scratch->bytes[v.ch2_fx1 + 1] = 0;
    EXPECT(cb_load_image(g_scratch, VIC) < 0 && g_scratch->info.problem_offset == v.ch2_fx1, "F00 rejected");
    g_scratch->bytes[v.ch2_fx1 + 1] = 3;
    EXPECT(cb_load_image(g_scratch, VIC) == 0 && g_scratch->info.start_speed[0] == 6 && g_scratch->info.start_speed[1] == 3,
           "F03 accepted: order 1 starts at speed 3 in straight play");
    expect_load(tb, TED, t.ch0_fx + 1, 2, t.ch0_fx, "W02 on voice 1");
    expect_load(tb, TED, t.ch0_fx + 1, 3, t.ch0_fx, "W03");
    expect_load(tb, TED, t.ch0_fx + 1, 0, -1, "W00 on voice 1");
    expect_load(tb, TED, t.ch2_fx, CB_FX_WAVE, t.ch2_fx, "Wxx on the DAC lane");
    free(vb);
    free(tb);
}

/* ---- fixtures: writes equal to the reference ------------------------------------------------- */

static void test_fixtures(void) {
    printf("fixture traces (%d songs)\n", CBT_SONG_COUNT);
    for (int i = 0; i < CBT_SONG_COUNT; ++i) {
        const CbtSong* s = &CBT_SONGS[i];
        CbmImage* img = fixture_image(s);
        const int chip = img->bytes[CB_H_CHIP];
        CbmMachine* m = machine(chip);
        TraceCtx ctx;
        memset(&ctx, 0, sizeof ctx);
        ctx.ref = s->trace;
        ctx.ref_bytes = s->trace_bytes;
        ctx.text = open_text(s->name);
        cbm_set_trace(m, on_trace, &ctx);
        int mode = -1;
        EXPECT(cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode) == CBM_OK && mode == CBM_SEEK_FROM_START, "%s: starts", s->name);
        const int v = chip * 2 + img->info.video;
        const double expect = (double)RATE * CBM_FRAME_CYCLES[v] / (img->info.multispeed * variant_clock(v));
        int lo = 1 << 30, hi = 0;
        for (uint32_t t = 0; t < s->ticks; ++t) {
            const int n = cbm_tick(m, g_tick);
            if (n < lo) lo = n;
            if (n > hi) hi = n;
        }
        if (ctx.text) fclose(ctx.text);
        EXPECT(ctx.mismatches == 0, "%s: every batch equals the reference's (%ld mismatches; first %s)", s->name, ctx.mismatches, ctx.first);
        EXPECT(ctx.at == ctx.ref_bytes, "%s: the reference's %u trace bytes all matched (%u)", s->name, ctx.ref_bytes, ctx.at);
        EXPECT(lo >= (int)floor(expect) - 1 && hi <= (int)ceil(expect) + 1, "%s: %d..%d frames per tick (%.2f expected)", s->name, lo,
               hi, expect);
        printf("  %s: %u ticks, %ld batches, %ld writes, %d..%d frames per tick\n", s->name, s->ticks, ctx.batches, ctx.writes, lo, hi);
        /* 20 s of audio, and a second start rendering the same samples. */
        cbm_set_trace(m, NULL, NULL);
        const long cap = 20L * RATE;
        float* a = frames_buffer(cap);
        float* b = frames_buffer(cap);
        const int ticks = (int)(20.0 * variant_clock(v) * img->info.multispeed / CBM_FRAME_CYCLES[v]);
        cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
        const long fa = run(m, ticks, a, cap);
        cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
        const long fb = run(m, ticks, b, cap);
        EXPECT(fa == fb && !memcmp(a, b, sizeof(float) * 2 * (size_t)(fa < cap ? fa : cap)), "%s: a second start renders the same samples",
               s->name);
        double pk = 0;
        for (long k = 0; k < 2 * (fa < cap ? fa : cap); ++k)
            if (fabs(a[k]) > pk) pk = fabs(a[k]);
        EXPECT(rms(a, 0, fa < cap ? fa : cap) > 0.005 && pk < 1.0, "%s: non-silent, unclipped (rms %.4f peak %.3f; unverified threshold)",
               s->name, rms(a, 0, fa < cap ? fa : cap), pk);
        char name[96];
        snprintf(name, sizeof name, "cbm_%s.wav", s->name);
        write_wav(name, a, fa < cap ? fa : cap);
        free(a);
        free(b);
        cbm_destroy(m);
        free(img);
    }
}

/* The four images exportSamples writes: text traces of 3000 ticks for the reference check. */
static void dump_exported(const char* samples) {
    static const char* const names[] = {"vic-demo", "vic-shortest", "ted-demo", "ted-shortest"};
    printf("exported images (%s)\n", samples);
    for (size_t i = 0; i < sizeof names / sizeof names[0]; ++i) {
        char path[512];
        snprintf(path, sizeof path, "%s/%s.cbimg", samples, names[i]);
        FILE* f = fopen(path, "rb");
        if (!f) {
            printf("  %s: not present (run `tools/build.sh exportSamples`)\n", path);
            continue;
        }
        CbmImage* img = new_image();
        const size_t n = fread(img->bytes, 1, CB_IMAGE_SIZE, f);
        fclose(f);
        const int chip = img->bytes[CB_H_CHIP];
        EXPECT(n == CB_IMAGE_SIZE && chip == (names[i][0] == 'v' ? VIC : TED) && cb_load_image(img, chip) == 0,
               "%s loads (%s at %d)", names[i], img->info.problem ? img->info.problem : "", img->info.problem_offset);
        if (img->info.loaded == CB_LOADED) {
            CbmMachine* m = machine(chip);
            TraceCtx ctx;
            memset(&ctx, 0, sizeof ctx);
            ctx.text = open_text(names[i]);
            cbm_set_trace(m, on_trace, &ctx);
            int mode;
            EXPECT(cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode) == CBM_OK, "%s starts", names[i]);
            const long frames = run(m, 3000, NULL, 0);
            EXPECT(frames > 0, "%s plays", names[i]);
            if (ctx.text) fclose(ctx.text);
            printf("  %s: 3000 ticks, %ld batches, %ld writes\n", names[i], ctx.batches, ctx.writes);
            cbm_destroy(m);
        }
        free(img);
    }
}

/* ---- actual audio ---------------------------------------------------------------------------- */

/* Renders `seconds` of an image from (0, 0) with optional mutes; returns the buffer (frames in *frames). */
static float* render_image(CbmImage* img, double seconds, unsigned mute, long* frames) {
    const int chip = img->bytes[CB_H_CHIP];
    CbmMachine* m = machine(chip);
    int mode;
    EXPECT(cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode) == CBM_OK, "start");
    for (int c = 0; c < CB_MAX_CHANNELS; ++c)
        if (mute >> c & 1) cbm_mute(m, c, 1);
    const int v = chip * 2 + img->info.video;
    const int ticks = (int)(seconds * variant_clock(v) * img->info.multispeed / CBM_FRAME_CYCLES[v]) + 1;
    const long cap = (long)(seconds * RATE) + 2 * CBM_MAX_TICK_FRAMES;
    float* buf = frames_buffer(cap);
    *frames = run(m, ticks, buf, cap);
    if (*frames > cap) *frames = cap;
    cbm_destroy(m);
    return buf;
}

static void expect_pitch(CbmImage* img, double want, const char* what, const char* wav) {
    long n = 0;
    float* buf = render_image(img, wav ? 2.0 : 1.2, 0, &n);
    const double f = measure_freq(buf, RATE / 5, n);
    EXPECT(fabs(f / want - 1) < 0.003, "%s: %.2f Hz measured, %.2f expected (0.3 %%; unverified threshold)", what, f, want);
    printf("  %s: %.3f Hz (%.3f expected)\n", what, f, want);
    if (wav) write_wav(wav, buf, n);
    free(buf);
}

static void test_pitch(void) {
    printf("pitch\n");
    CbmImage* img = new_image();
    /* The shortest songs: one order of one row, A-4 with instrument 1, PAL, speed 6. */
    tone_song(img->bytes, VIC, PAL, 2, A4, CB_WAVE_SQUARE, 1);
    EXPECT(load(img, img->bytes) == 0, "VIC shortest song loads");
    expect_pitch(img, 17734475.0 / 16 / (64 * 39), "VIC PAL soprano A-4 (a = 39)", "cbm_vic_shortest.wav");
    tone_song(img->bytes, TED, PAL, 0, A4, CB_WAVE_SQUARE, 1);
    EXPECT(load(img, img->bytes) == 0, "TED shortest song loads");
    expect_pitch(img, 17734475.0 / 80 / (2 * 252), "TED PAL voice 1 A-4 (P = 252)", "cbm_ted_shortest.wav");
    /* Spot checks per lane and variant (expected from the player's own period). */
    const struct { int chip, video, channel, note; const char* what; } spots[] = {
        {VIC, PAL, 0, 33, "VIC PAL bass A-2"},     {VIC, PAL, 1, 45, "VIC PAL alto A-3"},
        {VIC, NTSC, 2, A4, "VIC NTSC soprano A-4"}, {VIC, NTSC, 0, 30, "VIC NTSC bass F#2"},
        {TED, NTSC, 0, A4, "TED NTSC voice 1 A-4"}, {TED, PAL, 1, 69, "TED PAL voice 2 A-5"},
        {TED, PAL, 0, 40, "TED PAL voice 1 E-3"},
    };
    for (size_t i = 0; i < sizeof spots / sizeof spots[0]; ++i) {
        tone_song(img->bytes, spots[i].chip, spots[i].video, spots[i].channel, spots[i].note, CB_WAVE_SQUARE, 64);
        EXPECT(load(img, img->bytes) == 0, "%s song loads", spots[i].what);
        expect_pitch(img, lane_freq(spots[i].chip, spots[i].video, spots[i].channel, spots[i].note), spots[i].what, NULL);
    }
    free(img);
}

/* Bass A-2 (slot 2, plain) and soprano A-4 (slot 1, plain) at master volume `volume`. */
static void two_lane_song(uint8_t* b, int volume) {
    song_init(b, VIC, PAL, 6, volume, 0);
    tone(b, 1, CB_WAVE_SQUARE);
    tone(b, 2, CB_WAVE_SQUARE);
    set_pattern(b, 0, 0, key_pattern(b, 33, 2));
    set_pattern(b, 0, 2, key_pattern(b, A4, 1));
}

static void test_volume(void) {
    printf("master volume and its owner\n");
    CbmImage* full = new_image();
    CbmImage* half = new_image();
    two_lane_song(full->bytes, 15);
    two_lane_song(half->bytes, 7);
    EXPECT(load(full, full->bytes) == 0 && load(half, half->bytes) == 0, "two-lane songs load");
    for (int lane = 0; lane <= 2; lane += 2) {
        const unsigned mute = lane == 0 ? 1u << 2 : 1u << 0;
        long nf = 0, nh = 0;
        float* a = render_image(full, 1.2, mute, &nf);
        float* b = render_image(half, 1.2, mute, &nh);
        const double rf = rms(a, RATE / 5, nf), rh = rms(b, RATE / 5, nh);
        EXPECT(rf > 0.02 && rh < 0.8 * rf && rh > 0.2 * rf, "lane %d alone: volume 7 scales it (rms %.4f vs %.4f at 15; unverified)", lane,
               rh, rf);
        free(a);
        free(b);
    }
    /* The owner: soprano slot 1 with volume envelope 15, 12, 8, 4, 0 (held), bass plain; row 8 keys slot 2 on the soprano. */
    CbmImage* img = new_image();
    uint8_t* b = img->bytes;
    song_init(b, VIC, PAL, 6, 15, 0);
    tone(b, 1, CB_WAVE_SQUARE);
    tone(b, 2, CB_WAVE_SQUARE);
    static const uint8_t env[] = {15, 12, 8, 4, 0};
    envelope(b, 1, CB_ENV_VOLUME, env, 5, CB_ENV_NONE, CB_ENV_NONE);
    set_pattern(b, 0, 0, key_pattern(b, 33, 2));
    const uint8_t p2[] = {0x03, A4, 1, 0x80 | 6, 0x03, A4, 2, 0x80 | 126};
    set_pattern(b, 0, 2, data(b, p2, (int)sizeof p2));
    EXPECT(load(img, b) == 0, "owner song loads");
    CbmMachine* m = machine(VIC);
    int mode;
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    static const int want[] = {15, 12, 8, 4, 0, 0, 0};
    int ok = 1;
    for (int t = 0; t < 7; ++t) {
        cbm_tick(m, g_tick);
        ok &= cbm_player(m)->shadow[0x0E] == want[t];
    }
    EXPECT(ok && cbm_player(m)->owner == 2, "the soprano owns the master volume: $0E 15, 12, 8, 4, 0, ...");
    const long cap = 2L * RATE;
    float* buf = frames_buffer(cap);
    const long n = run(m, 30, buf, cap);
    EXPECT(cbm_player(m)->ch[0].sounding && rms(buf, RATE / 10, n) < 0.002,
           "volume 0 from the owner silences the sounding bass too (rms %.5f; unverified)", rms(buf, RATE / 10, n));
    run(m, 49 - 37, NULL, 0); /* through tick 48: row 8 keys slot 2 */
    EXPECT(cbm_player(m)->owner == -1 && cbm_player(m)->shadow[0x0E] == 15, "a key-on without a volume envelope ends ownership ($0E %d)",
           cbm_player(m)->shadow[0x0E]);
    free(buf);
    cbm_destroy(m);
    free(img);
    free(full);
    free(half);
}

static void test_noise(void) {
    printf("TED noise vs square, VIC noise\n");
    CbmImage* img = new_image();
    double ac[2], level[2];
    for (int w = 0; w < 2; ++w) {
        tone_song(img->bytes, TED, PAL, 1, A4, w ? CB_WAVE_NOISE : CB_WAVE_SQUARE, 64);
        EXPECT(load(img, img->bytes) == 0, "voice 2 song loads");
        long n = 0;
        float* buf = render_image(img, 1.2, 0, &n);
        const int lag = (int)lrint(RATE / lane_freq(TED, PAL, 1, A4));
        ac[w] = autocorr(buf, RATE / 5, n, lag);
        level[w] = rms(buf, RATE / 5, n);
        free(buf);
    }
    EXPECT(ac[0] > 0.8 && ac[1] < 0.5 && level[1] > 0.01, "noise is rough where the square repeats (autocorrelation at the period: "
           "square %.3f, noise %.3f; noise rms %.4f; unverified)", ac[0], ac[1], level[1]);
    tone_song(img->bytes, VIC, PAL, 3, 100, CB_WAVE_SQUARE, 64);
    EXPECT(load(img, img->bytes) == 0, "VIC noise song loads");
    CbmMachine* m = machine(VIC);
    int mode;
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    const long cap = RATE;
    float* buf = frames_buffer(cap);
    const long n = run(m, 50, buf, cap);
    EXPECT(cbm_player(m)->shadow[0x0D] == (0x80 | ((100 + 127) & 127)), "VIC noise rate 100 -> $0D = $%02X", cbm_player(m)->shadow[0x0D]);
    EXPECT(rms(buf, RATE / 5, n) > 0.005, "the VIC noise lane sounds (rms %.4f; unverified)", rms(buf, RATE / 5, n));
    free(buf);
    cbm_destroy(m);
    /* The unit's reset state: LFSR $FFFF, lfsr0_old 1. */
    CbVic vic;
    cbv_reset(&vic);
    EXPECT(vic.lfsr == 0xFFFF && vic.lfsr0_old == 1 && vic.volume == 0, "VIC reset: LFSR $FFFF, lfsr0_old 1");
    free(img);
}

/* A TED song with only the DAC lane: note 60 = root 60 of a looped sample, frames 16 x 0 then 16 x `level`. */
static void dac_song(uint8_t* b, int level, int timer) {
    song_init(b, TED, PAL, 6, 8, timer);
    uint8_t frames[32];
    for (int i = 0; i < 32; ++i) frames[i] = (uint8_t)(i < 16 ? 0 : level);
    sample(b, 0, frames, 32);
    sample_instrument(b, 1, 0, 60, 1, 0);
    set_pattern(b, 0, 2, key_pattern(b, 60, 1));
}

static void test_dac(void) {
    printf("TED D/A samples\n");
    CbmImage* img = new_image();
    dac_song(img->bytes, 8, 12);
    EXPECT(load(img, img->bytes) == 0, "DAC song loads");
    CbmMachine* m = machine(TED);
    TraceCtx ctx;
    memset(&ctx, 0, sizeof ctx);
    cbm_set_trace(m, on_trace, &ctx);
    int mode;
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    cbm_tick(m, g_tick);
    EXPECT(cbm_player(m)->dac && cbm_player(m)->shadow[0x11] == 0xB0, "the key-on enters D/A mode with frame 0 ($11 = $%02X)",
           cbm_player(m)->shadow[0x11]);
    const int irqs = cbm_timer_interrupts(m);
    EXPECT(irqs == 158 || irqs == 159, "T = 12: 17784 / 112 = 158.8 interrupts per tick (%d)", irqs);
    EXPECT(ctx.irq_count >= 2 && ctx.irq_index[0] == 15 && ctx.irq_val[0] == (0xB0 | 8) && ctx.irq_index[1] == 31 && ctx.irq_val[1] == 0xB0,
           "frames in order at the root: frame 16 at interrupt 15, the loop's frame 0 at interrupt 31");
    cbm_set_trace(m, NULL, NULL);
    cbm_destroy(m);
    /* The sample's 32-frame square: 7917.2 / 32 = 247.4 Hz; its level grows with the frame value. */
    double pp[3];
    static const int levels[3] = {2, 4, 8};
    for (int i = 0; i < 3; ++i) {
        dac_song(img->bytes, levels[i], 12);
        load(img, img->bytes);
        long n = 0;
        float* buf = render_image(img, 1.2, 0, &n);
        pp[i] = peak_to_peak(buf, RATE / 5, n);
        if (i == 2) {
            const double f = measure_freq(buf, RATE / 5, n), want = 17734475.0 / 20 / 112 / 32;
            EXPECT(fabs(f / want - 1) < 0.005, "sample square at %.2f Hz (%.2f: the timer rate; unverified threshold)", f, want);
        }
        free(buf);
    }
    EXPECT(pp[0] > 0.01 && pp[1] > pp[0] * 1.3 && pp[2] > pp[1] * 1.3, "D/A level steps: frame 2, 4, 8 -> %.4f, %.4f, %.4f (unverified)",
           pp[0], pp[1], pp[2]);
    /* Another rate: T = 28, 176 single clocks. */
    dac_song(img->bytes, 8, 28);
    load(img, img->bytes);
    m = machine(TED);
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    cbm_tick(m, g_tick);
    EXPECT(cbm_timer_interrupts(m) == 101 || cbm_timer_interrupts(m) == 102, "T = 28: 17784 / 176 = 101.0 interrupts per tick (%d)",
           cbm_timer_interrupts(m));
    cbm_destroy(m);
    /* The VIC has no timer. */
    tone_song(img->bytes, VIC, PAL, 2, A4, CB_WAVE_SQUARE, 64);
    load(img, img->bytes);
    m = machine(VIC);
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    cbm_tick(m, g_tick);
    EXPECT(cbm_timer_interrupts(m) == 0, "no interrupts on the VIC");
    cbm_destroy(m);
    free(img);
}

/* Runs the TED unit `sound_cycles` sound cycles from now (chunked into blip frames, output discarded). */
static void run_ted_unit(CbTed* t, blip_t* blip, long sound_cycles) {
    static short scratch[4096];
    while (sound_cycles > 0) {
        const long chunk = sound_cycles < 4000 ? sound_cycles : 4000;
        cbt_run(t, blip, 0, (unsigned)(chunk * 4));
        blip_end_frame(blip, (unsigned)(chunk * 4));
        while (blip_read_samples(blip, scratch, 4096, 0)) {
        }
        sound_cycles -= chunk;
    }
}

static void test_ted_decay(void) {
    printf("TED $3FE: no tone, decay to high\n");
    blip_t* blip = blip_new(4096);
    blip_set_rates(blip, 17734475.0 / 20, RATE);
    CbTed t;
    cbt_reset(&t);
    EXPECT(t.soundChannel1Reload == 0x3FF && t.soundChannel2Cnt == 0x3FF && t.soundChannel1State == 1 && t.soundChannel2NoiseState == 0xFF &&
               t.soundChannel1Decay == CBT_SOUND_DECAY_CYCLES && t.cycle_count == 0,
           "plus4emu's reset state");
    cbt_write(&t, 0x0E, 0xFE);
    cbt_write(&t, 0x12, 0x03);
    cbt_write(&t, 0x11, 0x18);
    EXPECT(t.soundChannel1Reload == 1, "x = $3FE reloads 1");
    /* The counter starts at $3FF after the reset: the first underflow (step 1023) toggles once, then every step
     * underflows again without a toggle; the decay, restarted at that toggle, sets the state high on step
     * 1023 + $2E000 - 1. */
    run_ted_unit(&t, blip, 1100);
    EXPECT(t.soundChannel1State == 0, "the first underflow toggles once, then none (state %d)", t.soundChannel1State);
    run_ted_unit(&t, blip, (long)CBT_SOUND_DECAY_CYCLES - 88);
    EXPECT(t.soundChannel1State == 0, "still low 10 sound cycles before the decay ends");
    run_ted_unit(&t, blip, 20);
    EXPECT(t.soundChannel1State == 1, "high after soundDecayCycles ($2E000 = %.2f s)", CBT_SOUND_DECAY_CYCLES / (17734475.0 / 80));
    /* An ordinary reload toggles every reload: x = 1023 - 252. */
    cbt_reset(&t);
    cbt_write(&t, 0x0E, (1023 - 252) & 0xFF);
    cbt_write(&t, 0x12, (1023 - 252) >> 8);
    cbt_write(&t, 0x11, 0x18);
    run_ted_unit(&t, blip, 1023); /* the reset count runs out: the first toggle */
    int toggles = 0, last = t.soundChannel1State;
    for (int i = 0; i < 252 * 10; ++i) {
        run_ted_unit(&t, blip, 1);
        if (t.soundChannel1State != last) ++toggles, last = t.soundChannel1State;
    }
    EXPECT(toggles == 10, "P = 252 toggles every 252 sound cycles (%d toggles in 2520)", toggles);
    blip_delete(blip);
}

/* Mutes: the output only. */
static void test_mute(void) {
    printf("mute\n");
    /* Silence and the other lanes. */
    CbmImage* img = new_image();
    two_lane_song(img->bytes, 15);
    load(img, img->bytes);
    long n = 0;
    float* all = render_image(img, 1.2, 0xF, &n);
    EXPECT(rms(all, RATE / 5, n) < 0.001, "VIC: every lane muted is silent (rms %.5f; unverified)", rms(all, RATE / 5, n));
    free(all);
    float* one = render_image(img, 1.2, 1, &n);
    EXPECT(rms(one, RATE / 5, n) > 0.01, "VIC: the soprano sounds with the bass muted (rms %.4f; unverified)", rms(one, RATE / 5, n));
    EXPECT(fabs(measure_freq(one, RATE / 5, n) / lane_freq(VIC, PAL, 2, A4) - 1) < 0.003, "VIC: what sounds is the soprano");
    free(one);
    tone_song(img->bytes, TED, PAL, 0, A4, CB_WAVE_SQUARE, 64);
    load(img, img->bytes);
    all = render_image(img, 1.2, 0x7, &n);
    EXPECT(rms(all, RATE / 5, n) < 0.001, "TED: every lane muted is silent (rms %.5f; unverified)", rms(all, RATE / 5, n));
    free(all);
    dac_song(img->bytes, 8, 12);
    load(img, img->bytes);
    all = render_image(img, 1.2, 1u << CB_TED_DAC_CHANNEL, &n);
    EXPECT(rms(all, RATE / 5, n) < 0.001, "TED: the muted DAC lane silences D/A mode (rms %.5f; unverified)", rms(all, RATE / 5, n));
    free(all);
    one = render_image(img, 1.2, 0x3, &n);
    EXPECT(rms(one, RATE / 5, n) > 0.01, "TED: voice mutes leave D/A mode sounding (rms %.4f; unverified)", rms(one, RATE / 5, n));
    free(one);
    free(img);
    /* Continuity on the fixture songs: chip state and writes bit-identical to an unmuted run while muted and after. */
    for (int i = 0; i < CBT_SONG_COUNT; ++i) {
        const CbtSong* s = &CBT_SONGS[i];
        CbmImage* fx = fixture_image(s);
        const int chip = fx->bytes[CB_H_CHIP];
        CbmMachine* a = machine(chip);
        CbmMachine* b = machine(chip);
        int mode;
        cbm_start(a, fx, 0, 0, CBM_SEEK_TICKS, &mode);
        cbm_start(b, fx, 0, 0, CBM_SEEK_TICKS, &mode);
        const int channels = chip == VIC ? CB_VIC_CHANNELS : CB_TED_CHANNELS;
        int same = 1, writes = 1;
        double muted_rms = 0, open_rms = 0;
        long muted_frames = 0;
        for (int t = 0; t < 400; ++t) {
            if (t == 50)
                for (int c = 0; c < channels; ++c) cbm_mute(b, c, 1);
            if (t == 250)
                for (int c = 0; c < channels; ++c) cbm_mute(b, c, 0);
            const int na_frames = cbm_tick(a, g_tick);
            if (t >= 70 && t < 250)
                for (int k = 0; k < na_frames; ++k) open_rms += (double)g_tick[2 * k] * g_tick[2 * k];
            static float gb[CBM_MAX_TICK_FRAMES * 2];
            const int nb = cbm_tick(b, gb);
            if (t >= 70 && t < 250) {
                for (int k = 0; k < nb; ++k) muted_rms += (double)gb[2 * k] * gb[2 * k];
                muted_frames += nb;
            }
            uint32_t sa[32], sb[32];
            const int na = cbm_chip_state(a, sa), nb2 = cbm_chip_state(b, sb);
            same &= na == nb2 && !memcmp(sa, sb, sizeof(uint32_t) * (size_t)na);
            const CbPlayer *pa = cbm_player(a), *pb = cbm_player(b);
            writes &= pa->writes == pb->writes && !memcmp(pa->write, pb->write, sizeof(CbWrite) * (size_t)pa->writes) &&
                      !memcmp(pa->shadow, pb->shadow, sizeof pa->shadow);
        }
        muted_rms = muted_frames ? sqrt(muted_rms / muted_frames) : 0;
        open_rms = muted_frames ? sqrt(open_rms / muted_frames) : 0;
        EXPECT(same, "%s: muting and unmuting every lane leaves the chip's state bit-identical to an unmuted run", s->name);
        EXPECT(writes, "%s: the player's writes are unchanged by mutes", s->name);
        /* The TED's output is 0 with every lane muted; the VIC's shared volume steps the DC level of its "+ 1" even with
         * every voice muted (the chip's, as VIC-20 digis use), so songs changing the volume keep those clicks. */
        if (chip == TED)
            EXPECT(muted_rms < 0.001, "%s: silent while every lane is muted (rms %.5f; unverified)", s->name, muted_rms);
        else
            EXPECT(muted_rms < 0.001 || muted_rms < 0.25 * open_rms, "%s: muted to volume-change clicks (rms %.5f vs %.5f; unverified)",
                   s->name, muted_rms, open_rms);
        EXPECT(cbm_mute(a, channels, 1) == CBM_ERR_IMAGE && cbm_mute(a, -1, 1) == CBM_ERR_IMAGE, "%s: mute channel limits", s->name);
        cbm_destroy(a);
        cbm_destroy(b);
        free(fx);
    }
}

/* Seeks: from the start, bit-identical to straight play; the order fallback. */
static void test_seek(void) {
    printf("seek\n");
    for (int i = 0; i < CBT_SONG_COUNT; ++i) {
        const CbtSong* s = &CBT_SONGS[i];
        CbmImage* fx = fixture_image(s);
        const int chip = fx->bytes[CB_H_CHIP];
        CbmMachine* a = machine(chip);
        int mode;
        cbm_start(a, fx, 0, 0, CBM_SEEK_TICKS, &mode);
        /* The first row instance entered at tick >= 60 for the first time. */
        static uint8_t seen[CB_MAX_ORDERS][256];
        memset(seen, 0, sizeof seen);
        int target = -1, to = 0, tr = 0;
        for (int t = 0; t < 3000 && target < 0; ++t) {
            int o, r, k;
            cbm_position(a, &o, &r, &k);
            if (k == 0) {
                if (t >= 60 && !seen[o][r]) target = t, to = o, tr = r;
                seen[o][r] = 1;
            }
            if (target < 0) cbm_tick(a, g_tick);
        }
        EXPECT(target > 0, "%s: a new row after 60 ticks", s->name);
        if (target > 0) {
            CbmMachine* b = machine(chip);
            EXPECT(cbm_start(b, fx, to, tr, CBM_SEEK_TICKS, &mode) == CBM_OK && mode == CBM_SEEK_FROM_START,
                   "%s: seek to order %d row %d from the start", s->name, to, tr);
            int o, r, k;
            cbm_position(b, &o, &r, &k);
            EXPECT(o == to && r == tr && k == 0, "%s: lands on its row", s->name);
            int same = 1;
            static float gb[CBM_MAX_TICK_FRAMES * 2];
            for (int t = 0; t < 200 && same; ++t) {
                const int na = cbm_tick(a, g_tick), nb = cbm_tick(b, gb);
                same = na == nb && !memcmp(g_tick, gb, sizeof(float) * 2 * (size_t)na);
            }
            EXPECT(same, "%s: 200 ticks after the seek bit-identical to straight play (tick %d)", s->name, target);
            cbm_destroy(b);
        }
        cbm_destroy(a);
        free(fx);
    }
    /* The order fallback: order 0 row 0 breaks to order 1 (D00), so order 0's rows 1..7 are unreachable. */
    CbmImage* img = new_image();
    uint8_t* b = img->bytes;
    song_init(b, VIC, PAL, 4, 15, 0);
    tone(b, 1, CB_WAVE_SQUARE);
    const uint8_t brk[] = {0x07, A4, 1, CB_FX_BREAK, 0, 0x80 | 126};
    const int p = data(b, brk, (int)sizeof brk);
    const int q = key_pattern(b, 60, 1);
    set_orders(b, 2, 0);
    set_rows(b, 0, 8);
    set_rows(b, 1, 8);
    set_pattern(b, 0, 2, p);
    set_pattern(b, 1, 2, q);
    EXPECT(load(img, b) == 0, "fallback song loads");
    CbmMachine* m = machine(VIC);
    int mode = -1, o, r, k;
    EXPECT(cbm_start(m, img, 1, 4, CBM_SEEK_TICKS, &mode) == CBM_OK && mode == CBM_SEEK_FROM_START, "order 1 row 4 from the start");
    EXPECT(cbm_start(m, img, 1, 4, 3, &mode) == CBM_OK && mode == CBM_SEEK_FROM_ORDER, "order 1 row 4 with 3 ticks of budget: from the order");
    cbm_position(m, &o, &r, &k);
    EXPECT(o == 1 && r == 4 && k == 0, "the fallback lands on its row");
    EXPECT(cbm_tick(m, g_tick) > 0, "and plays");
    EXPECT(cbm_start(m, img, 0, 3, CBM_SEEK_TICKS, &mode) == CBM_ERR_IMAGE, "a row behind a Dxx of its own order is unreachable");
    EXPECT(cbm_start(m, img, 2, 0, CBM_SEEK_TICKS, &mode) == CBM_ERR_IMAGE && cbm_start(m, img, 1, 8, CBM_SEEK_TICKS, &mode) == CBM_ERR_IMAGE &&
               cbm_start(m, img, -1, 0, CBM_SEEK_TICKS, &mode) == CBM_ERR_IMAGE,
           "targets outside the song rejected");
    cbm_destroy(m);
    free(img);
}

static void test_live_edits(void) {
    printf("live edits\n");
    CbmImage* img = new_image();
    CbmImage* edit = new_image();
    uint8_t* b = img->bytes;
    /* Envelope edit: the soprano's held volume envelope value 15 -> 5 is written at the next tick. */
    song_init(b, VIC, PAL, 6, 15, 0);
    tone(b, 1, CB_WAVE_SQUARE);
    static const uint8_t env[] = {15};
    const int at = envelope(b, 1, CB_ENV_VOLUME, env, 1, 0, CB_ENV_NONE);
    set_pattern(b, 0, 2, key_pattern(b, A4, 1));
    EXPECT(load(img, b) == 0, "edit song loads");
    CbmMachine* m = machine(VIC);
    int mode, o, r, k;
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    run(m, 3, NULL, 0);
    EXPECT(cbm_player(m)->shadow[0x0E] == 15 && cbm_player(m)->shadow[0x0C] == (0x80 | 88), "PAL soprano A-4: $0C = $D8, $0E = 15");
    memcpy(edit->bytes, b, CB_IMAGE_SIZE);
    edit->bytes[at] = 5;
    load(edit, edit->bytes);
    cbm_apply_image(m, edit);
    cbm_tick(m, g_tick);
    EXPECT(cbm_player(m)->shadow[0x0E] == 5, "the edited envelope is heard at the next tick ($0E %d)", cbm_player(m)->shadow[0x0E]);
    cbm_apply_image(m, img);
    cbm_tick(m, g_tick);
    /* Video: NTSC from the next tick (period 36, a 16965-cycle frame, ~796 frames). */
    memcpy(edit->bytes, b, CB_IMAGE_SIZE);
    edit->bytes[CB_H_VIDEO] = NTSC;
    load(edit, edit->bytes);
    int64_t c0 = cbm_cycle(m);
    const int pal_frames = cbm_tick(m, g_tick);
    EXPECT(cbm_cycle(m) - c0 == 22152 && pal_frames >= 958 && pal_frames <= 961, "PAL ticks: 22152 cycles, %d frames", pal_frames);
    cbm_apply_image(m, edit);
    c0 = cbm_cycle(m);
    const int ntsc_frames = cbm_tick(m, g_tick);
    EXPECT(cbm_player(m)->shadow[0x0C] == (0x80 | (127 - 36)), "NTSC: the soprano's period switches to 36 at the next tick ($0C = $%02X)",
           cbm_player(m)->shadow[0x0C]);
    EXPECT(cbm_cycle(m) - c0 == 16965 && ntsc_frames >= 794 && ntsc_frames <= 798, "NTSC ticks: 16965 cycles (%lld), %d frames",
           (long long)(cbm_cycle(m) - c0), ntsc_frames);
    /* Multispeed 2 halves the tick. */
    edit->bytes[CB_H_MULTISPEED] = 2;
    load(edit, edit->bytes);
    cbm_apply_image(m, edit);
    c0 = cbm_cycle(m);
    cbm_tick(m, g_tick);
    const int64_t d1 = cbm_cycle(m) - c0;
    cbm_tick(m, g_tick);
    EXPECT(d1 + (cbm_cycle(m) - c0 - d1) == 16965 && (d1 == 8482 || d1 == 8483), "x2: two ticks per 16965-cycle frame (%lld)", (long long)d1);
    cbm_destroy(m);
    /* Speed: the header's 6 -> 3 at (0, 0, tick 2) ends the row after this tick. */
    tone_song(b, VIC, PAL, 2, A4, CB_WAVE_SQUARE, 64);
    load(img, b);
    m = machine(VIC);
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    run(m, 2, NULL, 0);
    memcpy(edit->bytes, b, CB_IMAGE_SIZE);
    edit->bytes[CB_H_SPEED] = 3;
    load(edit, edit->bytes);
    cbm_apply_image(m, edit);
    EXPECT(cbm_player(m)->speed == 3, "the edited speed is taken (%d)", cbm_player(m)->speed);
    cbm_tick(m, g_tick);
    cbm_position(m, &o, &r, &k);
    EXPECT(o == 0 && r == 1 && k == 0, "the row ends after its third tick (%d, %d, %d)", o, r, k);
    cbm_apply_image(m, edit);
    EXPECT(cbm_player(m)->speed == 3, "an unchanged image keeps the speed");
    /* Volume header: 15 -> 9 sets the player's M. */
    edit->bytes[CB_H_VOLUME] = 9;
    load(edit, edit->bytes);
    cbm_apply_image(m, edit);
    cbm_tick(m, g_tick);
    EXPECT(cbm_player(m)->shadow[0x0E] == 9, "the edited start volume is written ($0E %d)", cbm_player(m)->shadow[0x0E]);
    /* An image of the other chip is ignored. */
    CbmImage* ted = new_image();
    tone_song(ted->bytes, TED, PAL, 0, A4, CB_WAVE_SQUARE, 64);
    load(ted, ted->bytes);
    cbm_position(m, &o, &r, &k);
    cbm_apply_image(m, ted);
    int o2, r2, k2;
    cbm_position(m, &o2, &r2, &k2);
    EXPECT(o == o2 && r == r2 && k == k2 && cbm_tick(m, g_tick) > 0 && cbm_player(m)->shadow[0x0C] == (0x80 | 88),
           "a TED image on the VIC machine is ignored");
    cbm_destroy(m);
    /* The TED's timer header field. */
    dac_song(b, 8, 12);
    load(img, b);
    m = machine(TED);
    cbm_start(m, img, 0, 0, CBM_SEEK_TICKS, &mode);
    cbm_tick(m, g_tick);
    memcpy(edit->bytes, b, CB_IMAGE_SIZE);
    edit->bytes[CB_H_TIMER] = 28;
    load(edit, edit->bytes);
    cbm_apply_image(m, edit);
    EXPECT(cbm_player(m)->timer == 28, "the edited start timer is taken");
    cbm_tick(m, g_tick);
    cbm_tick(m, g_tick);
    EXPECT(cbm_timer_interrupts(m) == 101 || cbm_timer_interrupts(m) == 102, "and paces the interrupts (%d per tick)", cbm_timer_interrupts(m));
    /* A slot removed under a sounding DAC note ends it at the next interrupt (no D/A mode). */
    memcpy(edit->bytes, b, CB_IMAGE_SIZE);
    edit->bytes[CB_H_TIMER] = 28;
    memset(edit->bytes + CB_OFF_INSTRUMENTS, 0, CB_INSTRUMENT_SIZE);
    memset(edit->bytes + CB_OFF_ORDERS, 0, 2 * CB_MAX_CHANNELS);
    edit->bytes[CB_H_INSTRUMENTS] = 0;
    EXPECT(load(edit, edit->bytes) == 0, "the edit without the instrument loads");
    cbm_apply_image(m, edit);
    cbm_tick(m, g_tick);
    EXPECT(!cbm_player(m)->dac && !(cbm_player(m)->shadow[0x11] & 0x80), "a removed sample slot stops its note");
    cbm_destroy(m);
    free(ted);
    free(img);
    free(edit);
}

static int ticks_until_end(CbmMachine* m, int limit) {
    int t = 0;
    while (t < limit && cbm_tick(m, g_tick) > 0) ++t;
    return t;
}

static void test_audition(void) {
    printf("audition\n");
    CbmImage* img = new_image();
    uint8_t* b = img->bytes;
    song_init(b, VIC, PAL, 6, 15, 0);
    tone(b, 1, CB_WAVE_SQUARE);
    tone(b, 2, CB_WAVE_SQUARE);
    static const uint8_t rel[] = {15, 15, 10, 5, 0};
    envelope(b, 2, CB_ENV_VOLUME, rel, 5, 1, 2);
    tone(b, 3, CB_WAVE_SQUARE);
    static const uint8_t held[] = {15, 15, 8};
    envelope(b, 3, CB_ENV_VOLUME, held, 3, 1, 2);
    EXPECT(load(img, b) == 0, "audition instruments load");
    CbmMachine* m = machine(VIC);
    /* Plain: A-4, no release point: release stops it at once. */
    EXPECT(cbm_audition(m, img, 2, A4, 1, 0) == CBM_OK, "audition A-4 on the soprano");
    const long cap = 2L * RATE;
    float* buf = frames_buffer(cap);
    long n = run(m, 60, buf, cap);
    EXPECT(cbm_player(m)->shadow[0x0C] == (0x80 | 88) && n > 50 * 958, "held: $0C = $D8, %ld frames", n);
    const double f = measure_freq(buf, RATE / 5, n);
    EXPECT(fabs(f / 444.072 - 1) < 0.003, "the audition sounds at 444.07 Hz (%.3f; unverified threshold)", f);
    EXPECT(cbm_release(m) == 0 && !(cbm_player(m)->shadow[0x0C] & 0x80), "release without a release point: silent now, gate written off");
    EXPECT(cbm_tick(m, g_tick) == 0, "then tick ends");
    /* Fine pitch +64 = A#4. */
    EXPECT(cbm_audition(m, img, 2, A4, 1, 64) == CBM_OK, "audition with fine +64");
    n = run(m, 60, buf, cap);
    const double want = lane_freq(VIC, PAL, 2, A4 + 1);
    EXPECT(fabs(measure_freq(buf, RATE / 5, n) / want - 1) < 0.003, "fine +64 = A#4 (%.2f Hz)", want);
    /* Release point: 10, 5, 0 then the end. */
    EXPECT(cbm_audition(m, img, 2, A4, 2, 0) == CBM_OK, "audition with a release point");
    run(m, 10, NULL, 0);
    EXPECT(cbm_player(m)->shadow[0x0E] == 15, "held at 15");
    EXPECT(cbm_release(m) == 1, "release: a release phase");
    int t = ticks_until_end(m, 100);
    EXPECT(t >= 2 && t <= 5, "it ends once the written volume is 0 at the envelope's end (%d ticks)", t);
    EXPECT(cbm_release(m) == 0, "a second release after the end: 0");
    /* Release point with a non-zero tail: the 10 s limit. */
    EXPECT(cbm_audition(m, img, 2, A4, 3, 0) == CBM_OK, "audition with a held tail");
    run(m, 5, NULL, 0);
    EXPECT(cbm_release(m) == 1, "release: a release phase");
    t = ticks_until_end(m, 2000);
    EXPECT(t >= 500 && t <= 502, "a tail that never reaches 0 ends 10 s after the release (%d ticks)", t);
    /* Release before any tick. */
    EXPECT(cbm_audition(m, img, 2, A4, 1, 0) == CBM_OK && cbm_release(m) == 0 && cbm_tick(m, g_tick) == 0, "a release before any tick cuts");
    /* The noise lane and the arguments. */
    EXPECT(cbm_audition(m, img, 3, 100, 1, 0) == CBM_OK && cbm_tick(m, g_tick) > 0 && cbm_player(m)->shadow[0x0D] == (0x80 | 99),
           "noise rate 100 audition");
    EXPECT(cbm_audition(m, img, 4, A4, 1, 0) == CBM_ERR_IMAGE, "VIC channel 4 rejected");
    EXPECT(cbm_audition(m, img, 2, 77, 1, 0) == CBM_ERR_IMAGE && cbm_audition(m, img, 2, 76, 1, 0) == CBM_OK, "soprano range 37..76 (PAL)");
    EXPECT(cbm_audition(m, img, 2, A4, 4, 0) == CBM_ERR_IMAGE && cbm_audition(m, img, 2, A4, 0, 0) == CBM_ERR_IMAGE, "undefined slots rejected");
    EXPECT(cbm_audition(m, img, 2, A4, 1, 128) == CBM_ERR_IMAGE && cbm_audition(m, img, 2, A4, 1, -128) == CBM_OK, "fine -128..127");
    cbm_destroy(m);
    /* TED: a one-shot sample ends by itself; placement rules. */
    song_init(b, TED, PAL, 6, 8, 12);
    tone(b, 1, CB_WAVE_SQUARE);
    tone(b, 2, CB_WAVE_NOISE);
    static uint8_t frames[2000];
    for (int i = 0; i < 2000; ++i) frames[i] = (uint8_t)(i & 8 ? 8 : 0);
    sample(b, 0, frames, 2000);
    sample_instrument(b, 3, 0, 60, 0, 0);
    EXPECT(load(img, b) == 0, "TED audition instruments load");
    m = machine(TED);
    EXPECT(cbm_audition(m, img, 2, 60, 3, 0) == CBM_OK, "DAC audition");
    t = ticks_until_end(m, 100);
    EXPECT(t >= 12 && t <= 14, "the one-shot ends with its 2000 frames at 158.8 per tick (%d ticks)", t);
    EXPECT(!cbm_player(m)->dac && !(cbm_player(m)->shadow[0x11] & 0x80), "D/A mode left at the end ($11 = $%02X)", cbm_player(m)->shadow[0x11]);
    EXPECT(cbm_audition(m, img, 0, A4, 3, 0) == CBM_ERR_IMAGE, "a sample instrument on voice 1 rejected");
    EXPECT(cbm_audition(m, img, 0, A4, 2, 0) == CBM_ERR_IMAGE && cbm_audition(m, img, 1, A4, 2, 0) == CBM_OK, "noise only on voice 2");
    EXPECT(cbm_audition(m, img, 2, A4, 1, 0) == CBM_ERR_IMAGE, "a tone on the DAC lane rejected");
    EXPECT(cbm_audition(m, img, 3, A4, 1, 0) == CBM_ERR_IMAGE, "TED channel 3 rejected");
    EXPECT(cbm_audition(m, img, 0, 32, 1, 0) == CBM_ERR_IMAGE && cbm_audition(m, img, 2, 109, 3, 0) == CBM_ERR_IMAGE, "TED lane ranges");
    /* A voice: release stops it and writes the control value at once. */
    EXPECT(cbm_audition(m, img, 0, A4, 1, 0) == CBM_OK && cbm_tick(m, g_tick) > 0 && (cbm_player(m)->shadow[0x11] & 0x10), "voice 1 gated on");
    EXPECT(cbm_release(m) == 0 && !(cbm_player(m)->shadow[0x11] & 0x10), "release writes $11 without voice 1 at once");
    cbm_destroy(m);
    free(buf);
    free(img);
}

/* The ops tables as the hosts drive them. */
static void test_ops(void) {
    printf("ops\n");
    const ChipEngineOps* vic = chip_engine_ops("vic20-vic");
    const ChipEngineOps* ted = chip_engine_ops("c16-ted");
    EXPECT(vic && ted && vic != ted, "both systems registered");
    if (!vic || !ted) return;
    EXPECT(vic->image_size == 131072 && ted->image_size == 131072 && vic->image_storage == sizeof(CbmImage) && !vic->row_serial &&
               !ted->row_serial,
           "image sizes, no row_serial");
    uint8_t* bytes = (uint8_t*)calloc(1, CB_IMAGE_SIZE);
    tone_song(bytes, VIC, PAL, 2, A4, CB_WAVE_SQUARE, 64);
    ChipImage* image = (ChipImage*)malloc(vic->image_storage);
    EXPECT(vic->load_image(image, bytes, CB_IMAGE_SIZE) == CHIP_OK, "VIC ops load a VIC image");
    EXPECT(ted->load_image(image, bytes, CB_IMAGE_SIZE) == CHIP_ERR_IMAGE, "TED ops reject a VIC image");
    EXPECT(vic->load_image(image, bytes, CB_IMAGE_SIZE - 1) == CHIP_ERR_IMAGE, "a short image rejected");
    vic->load_image(image, bytes, CB_IMAGE_SIZE);
    ChipMachine* m = vic->create(RATE);
    EXPECT(m && !vic->create(7000) && !vic->create(96001), "create checks the rate");
    int mode = -1;
    EXPECT(vic->start(m, image, 0, 3, 3600, &mode) == CHIP_OK && mode == CHIP_SEEK_FROM_START, "ops start");
    float out[CHIP_MAX_TICK_FRAMES * 2];
    const int n = vic->tick(m, out);
    EXPECT(n > 900 && n <= (int)CHIP_MAX_TICK_FRAMES, "ops tick (%d frames)", n);
    int o, r, k;
    vic->position(m, &o, &r, &k);
    EXPECT(o == 0 && r == 3 && k == 1, "ops position");
    EXPECT(vic->mute(m, 3, 1) == CHIP_OK && vic->mute(m, 4, 1) == CHIP_ERR_IMAGE, "ops mute");
    vic->apply_image(m, image);
    EXPECT(vic->audition(m, image, 2, A4, 1, 0) == CHIP_OK && vic->tick(m, out) > 0 && vic->release(m) == 0, "ops audition and release");
    vic->destroy(m);
    /* 96 kHz: a TED PAL tick fits the host buffer. */
    tone_song(bytes, TED, PAL, 0, A4, CB_WAVE_SQUARE, 64);
    EXPECT(ted->load_image(image, bytes, CB_IMAGE_SIZE) == CHIP_OK, "TED ops load a TED image");
    m = ted->create(96000);
    ted->start(m, image, 0, 0, 3600, &mode);
    int most = 0;
    for (int t = 0; t < 50; ++t) {
        const int f = ted->tick(m, out);
        if (f > most) most = f;
    }
    EXPECT(most >= 1924 && most <= (int)CBM_MAX_TICK_FRAMES, "TED PAL at 96 kHz: %d frames per tick at most", most);
    ted->destroy(m);
    free(image);
    free(bytes);
}

/* Tick cost: thread CPU time per tick over 30 s of each fixture song. */
static void test_cost(void) {
    printf("tick cost\n");
    for (int i = 0; i < CBT_SONG_COUNT; ++i) {
        const CbtSong* s = &CBT_SONGS[i];
        CbmImage* fx = fixture_image(s);
        const int chip = fx->bytes[CB_H_CHIP];
        CbmMachine* m = machine(chip);
        int mode;
        cbm_start(m, fx, 0, 0, CBM_SEEK_TICKS, &mode);
        const int v = chip * 2 + fx->info.video;
        const int per_second = (int)(variant_clock(v) * fx->info.multispeed / CBM_FRAME_CYCLES[v]);
        double sum = 0, worst = 0;
        int counted = 0;
        for (int t = 0; t < 30 * per_second; ++t) {
            struct timespec a, b;
            clock_gettime(CLOCK_THREAD_CPUTIME_ID, &a);
            cbm_tick(m, g_tick);
            clock_gettime(CLOCK_THREAD_CPUTIME_ID, &b);
            const double us = (b.tv_sec - a.tv_sec) * 1e6 + (b.tv_nsec - a.tv_nsec) / 1e3;
            if (t < per_second) continue; /* warm-up */
            sum += us;
            ++counted;
            if (us > worst) worst = us;
        }
        const double mean = counted ? sum / counted : 0;
        printf("  %s: %.1f us per tick mean, %.1f us worst (%.0fx realtime)\n", s->name, mean, worst,
               mean > 0 ? 1e6 / per_second / mean : 0);
        EXPECT(worst <= 3 * mean + 50, "%s: no tick above 3x the mean + 50 us (%.1f vs %.1f; unverified)", s->name, worst, mean);
        EXPECT(mean < 1000, "%s: under 1 ms per tick on the host (%.1f us; unverified)", s->name, mean);
        cbm_destroy(m);
        free(fx);
    }
}

/* Headroom regressions. The quiet parallel blip is a linearity oracle,
 * not an independent chip model. Raw chip diagnostics remain at physical gain. */
static void test_headroom(void) {
    static const int rates[] = {8000, 11025, 22050, 44100, 48000, 96000};
    short actual[256], quiet[256];
    for (int variant = 0; variant < 4; ++variant) {
        for (unsigned r = 0; r < sizeof rates / sizeof rates[0]; ++r) {
            const int chip = variant / 2, rate = rates[r];
            blip_t* b = blip_new(256);
            blip_t* q = blip_new(256);
            blip_set_rates(b, CBM_CLOCK_HZ[variant], rate);
            blip_set_rates(q, CBM_CLOCK_HZ[variant], rate);
            blip_clear(b);
            blip_clear(q);
            CbVic v;
            CbTed t;
            cbv_reset(&v);
            cbt_reset(&t);
            if (chip == TED) {
                cbt_write(&t, 0x12, 3);
                cbt_write(&t, 0x0E, 0xE5);
                cbt_write(&t, 0x10, 3);
                cbt_write(&t, 0x0F, 0x9A);
            }
            int prev = 0, peak = 0, error = 0, rails = 0;
            float lp = 0, hp = 0, output_peak = 0;
            const float lb = 1.0f / (1.0f + rate * 1e-4f);
            const float hb = 1.0f / (1.0f + rate * 1e-3f);
            /* All VIC voices run, including while muted. TED alternates maximum
             * DAC and square/noise paths, with long DC holds then opposite edges. */
            if (chip == VIC)
                for (int ch = 0; ch < 4; ++ch) cbv_write(&v, b, 0, 0x0A + ch, 0x80);
            for (int frame = 0; frame < 240; ++frame) {
                const unsigned clocks = (unsigned)(CBM_CLOCK_HZ[variant] / rate * 128);
                for (unsigned at = 0; at < clocks; ++at) {
                    const int volume = frame < 80 ? 15 : frame < 160 ? 0 :
                        (((at / 7 + (unsigned)frame) & 1) ? 15 : 0);
                    if (chip == VIC) {
                        cbv_write(&v, b, at, 0x0E, volume);
                        cbv_mute(&v, b, at, frame >= 180 && frame < 200 ? 15 : 0);
                        cbv_run(&v, b, at, at + 1);
                    } else {
                        cbt_write(&t, 0x11, (frame < 200 ? 0xB0 : frame < 220 ? 0x30 : 0x50) | volume);
                        cbt_mute(&t, frame >= 180 && frame < 190 ? 7 : 0);
                        cbt_run(&t, b, at, at + 1);
                    }
                    const int raw = chip == VIC ? v.level : t.level;
                    const int level = chip == VIC ? raw * 11 / 16 : raw;
                    const int half = level / 2;
                    if (half != prev) blip_add_delta(q, at, half - prev);
                    prev = half;
                }
                blip_end_frame(b, clocks);
                blip_end_frame(q, clocks);
                const int n = blip_read_samples(b, actual, 256, 0);
                EXPECT(blip_read_samples(q, quiet, 256, 0) == n, "headroom frame count");
                for (int i = 0; i < n; ++i) {
                    const int e = abs(actual[i] - 2 * quiet[i]);
                    if (e > error) error = e;
                    if (abs(actual[i]) > peak) peak = abs(actual[i]);
                    rails += actual[i] == 32767 || actual[i] == -32768;
                    float out = actual[i];
                    if (chip == VIC) {
                        out = lp - hp;
                        hp += hb * (lp - hp);
                        lp += lb * (actual[i] - lp);
                    }
                    if (fabsf(out) > output_peak) output_peak = fabsf(out);
                }
            }
            EXPECT(peak > 100 && !rails && error <= 8,
                   "chip %d video %d rate %d: peak %d rails %d half-scale error %d",
                   chip, variant & 1, rate, peak, rails, error);
            EXPECT(output_peak < 32768, "chip %d rate %d final output %g", chip, rate, output_peak);
            blip_delete(b);
            blip_delete(q);
        }
    }
    /* Construct the positive-lobe adversary from low-level one-clock impulses.
     * This isolates resampler clipping from the VIC's later analog filter.
     * All four voice bits hold high for <254 clocks, a legal counter interval;
     * only master-volume writes change during that interval. */
    for (int video = 0; video < 2; ++video) {
        const double clock = CBM_CLOCK_HZ[video];
        const unsigned clocks = (unsigned)ceil(clock * 20 / 96000);
        unsigned char high[256] = {0};
        blip_t* b = blip_new(64);
        blip_t* q = blip_new(64);
        blip_set_rates(b, clock, 96000);
        blip_set_rates(q, clock, 96000);
        blip_clear(b); /* Match the phase of the cleared impulse probes and quiet oracle. */
        for (unsigned at = 0; at < clocks; ++at) {
            blip_clear(q);
            blip_add_delta(q, at, 16384);
            blip_add_delta(q, at + 1, -16384);
            blip_end_frame(q, clocks);
            const int n = blip_read_samples(q, quiet, 64, 0);
            EXPECT(n > 17, "impulse probe reaches target");
            high[at] = quiet[17] > 0;
        }
        blip_clear(q);
        CbVic v;
        cbv_reset(&v);
        for (int ch = 0; ch < 4; ++ch) {
            v.ch[ch].reg = 0x80;
            v.ch[ch].shift = 255;
            v.ch[ch].out = 1;
            v.ch[ch].ctr = 254;
        }
        int previous = 0;
        for (unsigned at = 0; at < clocks; ++at) {
            cbv_write(&v, b, at, 0x0E, high[at] ? 15 : 0);
            cbv_run(&v, b, at, at + 1);
            EXPECT(v.level == (high[at] ? 29491 : 0), "raw VIC voltage unchanged");
            const int quarter = v.level / 4;
            if (quarter != previous) blip_add_delta(q, at, quarter - previous);
            previous = quarter;
        }
        blip_end_frame(b, clocks);
        blip_end_frame(q, clocks);
        const int n = blip_read_samples(b, actual, 64, 0);
        EXPECT(blip_read_samples(q, quiet, 64, 0) == n, "adversary frame count");
        EXPECT(4 * quiet[17] > 32767, "VIC %d unattenuated adversary exceeds int16: %d",
               video, 4 * quiet[17]);
        EXPECT(fabs(actual[17] - quiet[17] * 2.75) <= 8,
               "VIC %d pre-blip gain preserves peak: %d vs %g", video, actual[17], quiet[17] * 2.75);
        blip_delete(b);
        blip_delete(q);
    }
}

int main(int argc, char** argv) {
    g_dir = argc > 1 ? argv[1] : ".";
    const char* samples = argc > 2 ? argv[2] : "app/build/samples";
    printf("VIC-20 / C16 (cbm) machine test\n");
    test_tables();
    test_loader();
    test_fixtures();
    dump_exported(samples);
    test_pitch();
    test_volume();
    test_noise();
    test_dac();
    test_ted_decay();
    test_headroom();
    test_mute();
    test_seek();
    test_live_edits();
    test_audition();
    test_ops();
    test_cost();
    EXPECT(fixture("vic_pal") && fixture("vic_ntsc") && fixture("ted_pal") && fixture("ted_ntsc"), "the four fixture songs are present");
    printf("VIC-20 / C16: %d checks, %d failures\n", checks, failures);
    return failures ? 1 : 0;
}
